//! Turbodoc's icon set: one 16-point grid, 1.3-point round strokes, drawn for this app so every
//! glyph reads as one family at 14–18 points. Rune rasterises the SVG bodies into its atlas.
use rune::Icon;

macro_rules! icon {
    ($name:ident, $id:literal, $body:literal) => {
        pub static $name: Icon = Icon { name: concat!("td-", $id), view: 16.0, body: $body };
    };
}

